
:host {
	height: 100dvh;
}

.app-container {
	min-height: 100dvh;
	display: flex;
	flex-direction: column;
}

html:has(.popover-modal.open){
	overflow: hidden;
}

header {
  background: #000;
  color: white;
  height: 56px;
  display: flex;
  align-items: center;
  box-shadow: 0 2px 5px 0 rgba(0, 0, 0, 0.26);
}

.header-icon {
	height: 35px;
	width: auto;
	padding-left: 25px;
}

header h1 {
	margin: 5px 0 0;
}

h1 {
  font-size: 1.4rem;
  font-weight: 500;
  padding: 0 12px;
}

main {
	display: flex;
	flex-direction: column;
	flex-grow: 1;
}

#ts-loader {
	display: flex;
	position: fixed;
	z-index: 100;
	top: 0;
	width: 100%;
	height: 100%;
	align-items: center;
	justify-content: center;
	background-color: rgba(87, 87, 87, 0.67)
}

.icon-small {
    width: 40px;
    height: 40px;
    margin-right: 8px;
}

.turnstile-widget {
	position: fixed;
	top: 0;
	left: 0;
	width: 100%;
	height: 100dvh;
	display: flex;
	align-items: center;
	justify-content: center;
	z-index: 999;
}

.grecaptcha-badge {
	z-index: 999;
}
